//! Built-in providers and their model catalogs.
//!
//! The catalogs in `crates/zp-ai/catalog/` are generated by `scripts/update_catalog.py`.

use std::sync::Arc;

use crate::model::{Api, Model};
use crate::provider::{HttpProvider, Provider};

struct BuiltinProvider {
    id: &'static str,
    name: &'static str,
    env_vars: &'static [&'static str],
    default_model: &'static str,
    /// Main endpoint, used for model listing and models the catalog lacks.
    api: Api,
    base_url: &'static str,
    /// Matching provider on models.dev.
    models_dev_id: &'static str,
    catalog: &'static str,
}

