/// Instantiates every built-in provider.
pub fn builtin_providers() -> Vec<Arc<dyn Provider>> {
    BUILTIN_PROVIDERS
        .iter()
        .map(|spec| {
            let models: Vec<Model> = serde_json::from_str(spec.catalog).unwrap_or_else(|error| {
                // The catalogs are compiled in and covered by tests, so this is a build bug.
                tracing::error!(provider = spec.id, %error, "invalid built-in catalog");
                Vec::new()
            });
            Arc::new(
                HttpProvider::new(spec.id, spec.name, spec.env_vars.iter().copied(), models)
                    .with_default_model(spec.default_model)
                    .with_api_endpoint(spec.api, spec.base_url)
                    .with_models_dev_id(spec.models_dev_id),
            ) as Arc<dyn Provider>
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_catalog_parses_and_has_its_default_model() {
        for spec in BUILTIN_PROVIDERS {
            let models: Vec<Model> = serde_json::from_str(spec.catalog)
                .unwrap_or_else(|error| panic!("{}: {error}", spec.id));
            assert!(!models.is_empty(), "{} has no models", spec.id);
            assert!(
                models.iter().any(|model| model.id == spec.default_model),
                "{}: default model {} missing",
                spec.id,
                spec.default_model
            );
            assert!(
                models
                    .iter()
                    .any(|model| model.api == spec.api && model.base_url == spec.base_url),
                "{}: no catalog model uses the provider endpoint",
                spec.id
            );
            for model in &models {
                assert_eq!(model.provider, spec.id);
                assert!(matches!(
                    model.api,
                    Api::AnthropicMessages | Api::OpenAiCompletions
                ));
                assert!(model.base_url.starts_with("https://"), "{}", model.id);
            }
        }
    }
}
